// Today's sky for one place, midnight to midnight: the background is the
// sky's color through the day (night, astronomical, nautical and civil
// twilight, golden hour, day), the sun's path is drawn over it with the
// horizon across, the moon's path beside it, and underneath how long the day
// is, when the light comes and goes, and how the moon is. All of it is worked
// out on the frame from the place's latitude and longitude.
import { WEEKDAYS, MONTHS, timeText, two } from './time'
import { sunAltitude, moonAltitude, moonIllumination, moonPhaseName, moonPath } from './sun'

const STEP = 5 * 60000

// The sky's color by the sun's altitude.
const SKY: [number, string][] = [
  [-18, '#0a1024'],
  [-12, '#141d43'],
  [-6, '#26356e'],
  [-2, '#57508a'],
  [0, '#b56f72'],
  [3, '#e0975e'],
  [6, '#e9b56f'],
  [10, '#7fa6d6'],
  [25, '#5a8fd0'],
]

function hex(value: number) {
  const text = Math.max(0, Math.min(255, Math.round(value))).toString(16)
  return text.length < 2 ? '0' + text : text
}

function mix(a: string, b: string, t: number) {
  const pa = parseInt(a.substring(1), 16)
  const pb = parseInt(b.substring(1), 16)
  return '#' + hex(((pa >> 16) & 255) * (1 - t) + ((pb >> 16) & 255) * t) +
    hex(((pa >> 8) & 255) * (1 - t) + ((pb >> 8) & 255) * t) + hex((pa & 255) * (1 - t) + (pb & 255) * t)
}

function skyAt(altitude: number) {
  if (altitude <= SKY[0][0]) return SKY[0][1]
  for (let i = 1; i < SKY.length; i++) {
    if (altitude <= SKY[i][0]) return mix(SKY[i - 1][1], SKY[i][1], (altitude - SKY[i - 1][0]) / (SKY[i][0] - SKY[i - 1][0]))
  }
  return SKY[SKY.length - 1][1]
}

// When a series of altitudes crosses a level, rising or setting.
function crossings(start: number, values: number[], level: number) {
  const found: { at: number; rising: boolean }[] = []
  for (let i = 1; i < values.length; i++) {
    const a = values[i - 1] - level
    const b = values[i] - level
    if ((a < 0 && b >= 0) || (a >= 0 && b < 0)) {
      found.push({ at: start + (i - 1 + a / (a - b)) * STEP, rising: b >= 0 })
    }
  }
  return found
}

function series(start: number, steps: number, altitude: (ms: number) => number) {
  const values = []
  for (let i = 0; i <= steps; i++) values.push(altitude(start + i * STEP))
  return values
}

function lengthText(ms: number) {
  const minutes = Math.round(ms / 60000)
  return `${Math.floor(minutes / 60)}h ${two(minutes % 60)}m`
}

function changeText(ms: number) {
  const seconds = Math.round(Math.abs(ms) / 1000)
  if (seconds < 5) return 'the same as yesterday'
  const text = (seconds >= 60 ? Math.floor(seconds / 60) + 'm ' : '') + (seconds % 60) + 's'
  return `${ms > 0 ? '+' : '−'}${text} on yesterday`
}

// The next moment the moon reaches a phase (0 new, 0.5 full), within a month.
function nextPhase(from: number, target: number) {
  let previous = moonIllumination(from).phase
  for (let t = from + 3 * 3600000; t < from + 31 * 86400000; t += 3 * 3600000) {
    const phase = moonIllumination(t).phase
    const crossed = target === 0 ? phase < previous - 0.5 : previous < target && phase >= target
    if (crossed) return t
    previous = phase
  }
  return null
}

export function get(app: FrameOSApp, context: FrameOSContext) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const place = app.config.place || {}
  if (place.latitude == null) {
    throw new Error(place.error || 'No place yet')
  }
  const lat = Number(place.latitude)
  const lon = Number(place.longitude)
  const twelve = app.config.clock === '12h'
  const nowDate = new Date()
  const now = nowDate.getTime()
  const midnight = new Date(nowDate.getFullYear(), nowDate.getMonth(), nowDate.getDate()).getTime()
  const dayLength = new Date(nowDate.getFullYear(), nowDate.getMonth(), nowDate.getDate() + 1).getTime() - midnight
  const steps = Math.round(dayLength / STEP)
  const clock = (ms: number) => {
    const d = new Date(ms)
    return timeText(d.getHours(), d.getMinutes(), twelve)
  }

  const sun = series(midnight, steps, (t) => sunAltitude(t, lat, lon))
  const moon = series(midnight, steps, (t) => moonAltitude(t, lat, lon))
  const yesterday = series(midnight - 86400000, 288, (t) => sunAltitude(t, lat, lon))
  const rises = crossings(midnight, sun, -0.833)
  const sunrise = rises.find((c) => c.rising)
  const sunset = rises.find((c) => !c.rising)
  // Daylight to the minute from the crossings, not the five-minute samples.
  const lengthOf = (start: number, values: number[]) => {
    const cs = crossings(start, values, -0.833)
    if (!cs.length) return values[0] > -0.833 ? values.length * STEP : 0
    let total = 0
    let from = values[0] > -0.833 ? start : null
    for (const c of cs) {
      if (c.rising) from = c.at
      else if (from != null) {
        total += c.at - from
        from = null
      }
    }
    if (from != null) total += start + (values.length - 1) * STEP - from
    return total
  }
  const daylight = lengthOf(midnight, sun)
  const daylightYesterday = lengthOf(midnight - 86400000, yesterday)
  const golden = crossings(midnight, sun, 6).filter((c) => !c.rising).pop()
  const dark = crossings(midnight, sun, -18).find((c) => !c.rising)
  const noonIndex = sun.indexOf(Math.max(...sun))
  const noon = midnight + noonIndex * STEP
  const sunNow = sunAltitude(now, lat, lon)
  const moonNow = moonAltitude(now, lat, lon)
  const lit = moonIllumination(now)
  const full = nextPhase(now, 0.5)

  if (context.round === true) {
    return roundSky({ W, H, place, nowDate, now, midnight, dayLength, steps, sun, moon, sunrise, sunset, sunNow, lit, full, daylight, daylightYesterday, clock })
  }

  const portrait = H > W
  const u = Math.min(W, H) / 100
  const pad = u * 5
  const chartLeft = pad
  const chartRight = W - pad
  const chartTop = u * 15
  const chartBottom = H * (portrait ? 0.6 : 0.64)
  const low = -24
  const high = Math.max(20, Math.max(...sun), Math.max(...moon)) + 8
  const x = (ms: number) => chartLeft + ((ms - midnight) / dayLength) * (chartRight - chartLeft)
  const y = (alt: number) => chartBottom - ((Math.max(low, alt) - low) / (high - low)) * (chartBottom - chartTop)
  const horizonY = y(0)

  // The sky, a stop every half hour.
  const stops = []
  for (let i = 0; i <= steps; i += 6) {
    stops.push(<stop offset={(i / steps).toFixed(4)} stopColor={skyAt(sun[i])} />)
  }
  const path = (values: number[], keep: (a: number) => boolean) => {
    let d = ''
    let drawing = false
    values.forEach((a, i) => {
      if (keep(a)) {
        d += `${drawing ? 'L' : 'M'}${x(midnight + i * STEP).toFixed(1)} ${y(a).toFixed(1)} `
        drawing = true
      } else {
        drawing = false
      }
    })
    return d
  }
  const ticks = []
  for (let h = 0; h <= 24; h += portrait ? 6 : 3) {
    const tx = x(midnight + h * 3600000)
    ticks.push(<line x1={tx} y1={chartBottom} x2={tx} y2={chartBottom + u * 1.2} stroke="#8d9bc0" strokeWidth={u * 0.25} />)
    if (h < 24 || !portrait) {
      ticks.push(
        <text x={tx} y={chartBottom + u * 4.6} fontFamily="FiraGO" fontSize={u * 3} fill="#8d9bc0" textAnchor={h === 0 ? 'start' : h === 24 ? 'end' : 'middle'}>
          {twelve ? (h % 12 || 12) + (h < 12 || h === 24 ? 'a' : 'p') : two(h % 24)}
        </text>,
      )
    }
  }
  const marks = []
  for (const c of [sunrise, sunset]) {
    if (!c) continue
    const cx = x(c.at)
    marks.push(<circle cx={cx} cy={horizonY} r={u * 0.9} fill="#ffd36b" />)
    marks.push(
      <text x={cx} y={horizonY + u * 5} fontFamily="FiraGO" fontWeight={600} fontSize={u * 3.2} fill="#ffffff" textAnchor="middle">
        {clock(c.at)}
      </text>,
    )
  }
  const noonX = x(noon)
  const noonY = y(sun[noonIndex])
  const sunX = x(now)
  const sunY = y(sunNow)
  const moonY = y(moonNow)
  const moonR = u * 2.3

  const facts = [
    { label: 'Daylight', value: lengthText(daylight), note: changeText(daylight - daylightYesterday) },
    {
      label: 'Sunrise · sunset',
      value: sunrise && sunset ? `${clock(sunrise.at)} · ${clock(sunset.at)}` : sun[noonIndex] > 0 ? 'Up all day' : 'Down all day',
      note: `Highest at ${clock(noon)}, ${Math.round(sun[noonIndex])}°`,
    },
    {
      label: 'Golden hour',
      value: golden && sunset ? `${clock(golden.at)} – ${clock(sunset.at)}` : '—',
      note: dark ? `Fully dark from ${clock(dark.at)}` : 'Never fully dark',
    },
    {
      label: 'Moon',
      value: `${moonPhaseName(lit.phase)}`,
      note: `${Math.round(lit.fraction * 100)}% lit` + (full ? ` · full ${new Date(full).getDate()} ${MONTHS[new Date(full).getMonth()].substring(0, 3)}` : ''),
      moon: true,
    },
  ]
  const columns = portrait ? 2 : 4
  const factTop = chartBottom + u * (portrait ? 10 : 9)
  const factW = (W - pad * 2) / columns
  const factH = Math.min((H - factTop - pad) / (portrait ? 2 : 1), u * 18)

  return (
    <svg viewBox={`0 0 ${W} ${H}`} width={W} height={H}>
      <linearGradient id="sky" gradientUnits="userSpaceOnUse" x1={chartLeft} y1="0" x2={chartRight} y2="0">
        {stops}
      </linearGradient>
      <linearGradient id="ground" gradientUnits="userSpaceOnUse" x1="0" y1={horizonY} x2="0" y2={chartBottom}>
        <stop offset="0" stopColor="#000000" stopOpacity="0.35" />
        <stop offset="1" stopColor="#000000" stopOpacity="0.6" />
      </linearGradient>
      <radialGradient id="glow" gradientUnits="userSpaceOnUse" cx={sunX} cy={sunY} r={u * 9}>
        <stop offset="0" stopColor="#ffe7a6" stopOpacity="0.7" />
        <stop offset="1" stopColor="#ffe7a6" stopOpacity="0" />
      </radialGradient>
      <rect width={W} height={H} fill="#0a1024" />

      <text x={pad} y={u * 8} fontFamily="FiraGO" fontWeight={600} fontSize={u * 4.2} fill="#ffffff">
        {(place.name ? place.name + ' · ' : '') + `${WEEKDAYS[nowDate.getDay()]} ${nowDate.getDate()} ${MONTHS[nowDate.getMonth()]}`}
      </text>
      <text x={W - pad} y={u * 8} fontFamily="FiraGO" fontSize={u * 3.4} fill="#aab5d4" textAnchor="end">
        {`${clock(now)} · sun ${sunNow >= 0 ? Math.round(sunNow) + '° up' : Math.round(-sunNow) + '° down'}`}
      </text>

      <rect x={chartLeft} y={chartTop} width={chartRight - chartLeft} height={chartBottom - chartTop} rx={u * 1.5} fill="url(#sky)" />
      <rect x={chartLeft} y={horizonY} width={chartRight - chartLeft} height={chartBottom - horizonY} fill="url(#ground)" />
      <line x1={chartLeft} y1={horizonY} x2={chartRight} y2={horizonY} stroke="#ffffff" strokeWidth={u * 0.3} opacity={0.6} />
      <path d={path(moon, (a) => a > low + 0.5)} fill="none" stroke="#d6def0" strokeWidth={u * 0.35} strokeLinejoin="round" opacity={0.45} />
      <path d={path(sun, (a) => a < 0 && a > low + 0.5)} fill="none" stroke="#ffd36b" strokeWidth={u * 0.5} strokeLinejoin="round" opacity={0.35} />
      <path d={path(sun, (a) => a >= -0.5)} fill="none" stroke="#ffd36b" strokeWidth={u * 0.8} strokeLinecap="round" strokeLinejoin="round" />
      {marks}
      {sun[noonIndex] > 0 ? (
        <text x={noonX} y={noonY - u * 2} fontFamily="FiraGO" fontSize={u * 3} fill="#ffffff" textAnchor="middle" opacity={0.85}>
          {`${Math.round(sun[noonIndex])}°`}
        </text>
      ) : null}
      <line x1={sunX} y1={chartTop} x2={sunX} y2={chartBottom} stroke="#ffffff" strokeWidth={u * 0.2} opacity={0.35} />
      <circle cx={sunX} cy={moonY} r={moonR} fill="#2b3350" />
      <path d={moonPath(sunX, moonY, moonR, lit.phase)} fill="#eef1f8" />
      <rect x={sunX - u * 9} y={sunY - u * 9} width={u * 18} height={u * 18} fill="url(#glow)" />
      <circle cx={sunX} cy={sunY} r={u * 2} fill="#ffdf85" stroke="#fff3cc" strokeWidth={u * 0.4} />
      {ticks}

      {facts.map((fact, i) => {
        const fx = pad + (i % columns) * factW
        const fy = factTop + Math.floor(i / columns) * factH
        const textX = fact.moon ? fx + u * 6.2 : fx
        return (
          <g>
            <line x1={fx} y1={fy} x2={fx + factW - u * 3} y2={fy} stroke="#2a3558" strokeWidth={u * 0.3} />
            {fact.moon ? (
              <g>
                <circle cx={fx + u * 2.8} cy={fy + u * 8} r={u * 2.6} fill="#2b3350" />
                <path d={moonPath(fx + u * 2.8, fy + u * 8, u * 2.6, lit.phase)} fill="#eef1f8" />
              </g>
            ) : null}
            <text x={textX} y={fy + u * 4.2} fontFamily="FiraGO" fontWeight={600} fontSize={u * 2.8} fill="#8d9bc0">
              {fact.label.toUpperCase()}
            </text>
            <text x={textX} y={fy + u * 9.2} fontFamily="FiraGO" fontWeight={600} fontSize={Math.min(u * 4.6, (factW - (textX - fx) - u * 3) / (fact.value.length * 0.56))} fill="#ffffff">
              {fact.value}
            </text>
            <text x={textX} y={fy + u * 13} fontFamily="FiraGO" fontSize={Math.min(u * 2.9, (factW - (textX - fx) - u * 2) / (fact.note.length * 0.47))} fill="#aab5d4">
              {fact.note}
            </text>
          </g>
        )
      })}
    </svg>
  )
}

// A round panel's whole canvas: the day is a 24-hour dial, midnight at the
// bottom and noon at the top, the sky's color through the day a ring along
// the rim with the moon's hours inside it and the sun where it is now; the
// place, the time, the light and the moon in the middle.
function roundSky({ W, H, place, nowDate, now, midnight, dayLength, steps, sun, moon, sunrise, sunset, sunNow, lit, full, daylight, daylightYesterday, clock }) {
  const S = Math.min(W, H)
  const cx = W / 2
  const cy = H / 2
  const k = S / 466
  const outer = S / 2 - 4 * k
  const band = 30 * k
  const inner = outer - band
  const mid = (outer + inner) / 2
  const f = (n: number) => n.toFixed(1)
  // Radians from the top, clockwise: midnight at the bottom.
  const angle = (ms: number) => Math.PI + ((ms - midnight) / dayLength) * Math.PI * 2
  const at = (a: number, r: number) => [cx + Math.sin(a) * r, cy - Math.cos(a) * r]
  const segment = (a1: number, a2: number, r1: number, r2: number) => {
    const [x1, y1] = at(a1, r2)
    const [x2, y2] = at(a2, r2)
    const [x3, y3] = at(a2, r1)
    const [x4, y4] = at(a1, r1)
    const large = a2 - a1 > Math.PI ? 1 : 0
    return `M${f(x1)} ${f(y1)} A${f(r2)} ${f(r2)} 0 ${large} 1 ${f(x2)} ${f(y2)} L${f(x3)} ${f(y3)} A${f(r1)} ${f(r1)} 0 ${large} 0 ${f(x4)} ${f(y4)} Z`
  }

  // The sky, a slice every half hour.
  const slices = []
  for (let i = 0; i < steps; i += 6) {
    const a1 = angle(midnight + i * STEP)
    const a2 = angle(midnight + Math.min(steps, i + 6) * STEP) + 0.01
    slices.push(<path d={segment(a1, a2, inner, outer)} fill={skyAt(sun[Math.min(steps, i + 3)])} />)
  }
  // The moon's hours above the horizon: a thin arc inside the ring.
  const moonArcs = []
  let from = -1
  for (let i = 0; i <= steps; i++) {
    const up = moon[i] > 0 && i < steps
    if (up && from < 0) from = i
    if (!up && from >= 0) {
      moonArcs.push(<path d={segment(angle(midnight + from * STEP), angle(midnight + i * STEP), inner - 9 * k, inner - 5 * k)} fill="#d6def0" opacity={0.5} />)
      from = -1
    }
  }
  const ticks = []
  for (let h = 0; h < 24; h += 3) {
    const a = angle(midnight + h * 3600000)
    const [x1, y1] = at(a, inner)
    const [x2, y2] = at(a, inner + (h % 6 === 0 ? 10 : 6) * k)
    ticks.push(<line x1={f(x1)} y1={f(y1)} x2={f(x2)} y2={f(y2)} stroke="#8d9bc0" strokeWidth={2 * k} opacity={0.6} />)
  }
  // Sunrise and sunset: a mark across the ring, the time just inside it.
  const marks = []
  for (const c of [sunrise, sunset]) {
    if (!c) continue
    const a = angle(c.at)
    const [x1, y1] = at(a, inner - 2 * k)
    const [x2, y2] = at(a, outer)
    const [tx, ty] = at(a, inner - 30 * k)
    marks.push(<line x1={f(x1)} y1={f(y1)} x2={f(x2)} y2={f(y2)} stroke="#ffd36b" strokeWidth={2.5 * k} />)
    marks.push(
      <text x={f(tx)} y={f(ty + 5 * k)} fontFamily="FiraGO" fontWeight={600} fontSize={f(15 * k)} fill="#ffd36b" textAnchor="middle">
        {clock(c.at)}
      </text>,
    )
  }
  const nowA = angle(now)
  const [sx, sy] = at(nowA, mid)
  const [nx1, ny1] = at(nowA, inner - 12 * k)
  const sunUp = sunNow >= 0
  const moonR = 13 * k
  const moonY = cy + 112 * k
  const moonText = `${moonPhaseName(lit.phase)} · ${Math.round(lit.fraction * 100)}%`
  const title = place.name || `${WEEKDAYS[nowDate.getDay()]}`
  const date = (place.name ? WEEKDAYS[nowDate.getDay()] + ' ' : '') + `${nowDate.getDate()} ${MONTHS[nowDate.getMonth()]}`
  const fit = (text: string, size: number, width: number) => Math.min(size, width / (text.length * 0.56))

  return (
    <svg viewBox={`0 0 ${W} ${H}`} width={W} height={H}>
      <radialGradient id="glow" gradientUnits="userSpaceOnUse" cx={f(sx)} cy={f(sy)} r={f(34 * k)}>
        <stop offset="0" stopColor="#ffe7a6" stopOpacity="0.8" />
        <stop offset="1" stopColor="#ffe7a6" stopOpacity="0" />
      </radialGradient>
      <rect width={W} height={H} fill="#0a1024" />
      {slices}
      <circle cx={f(cx)} cy={f(cy)} r={f(inner)} fill="none" stroke="#2a3558" strokeWidth={f(1.5 * k)} />
      <circle cx={f(cx)} cy={f(cy)} r={f(outer)} fill="none" stroke="#2a3558" strokeWidth={f(1.5 * k)} />
      {ticks}
      {moonArcs}
      {marks}
      <line x1={f(nx1)} y1={f(ny1)} x2={f(sx)} y2={f(sy)} stroke="#ffffff" strokeWidth={1.5 * k} opacity={0.5} />
      {sunUp ? <rect x={f(sx - 34 * k)} y={f(sy - 34 * k)} width={f(68 * k)} height={f(68 * k)} fill="url(#glow)" /> : null}
      <circle cx={f(sx)} cy={f(sy)} r={f(10 * k)} fill={sunUp ? '#ffdf85' : '#3a4262'} stroke={sunUp ? '#fff3cc' : '#ffd36b'} strokeWidth={f(2 * k)} />

      <text x={f(cx)} y={f(cy - 98 * k)} fontFamily="FiraGO" fontWeight={600} fontSize={f(fit(title, 19 * k, 220 * k))} fill="#ffffff" textAnchor="middle">
        {title}
      </text>
      <text x={f(cx)} y={f(cy - 74 * k)} fontFamily="FiraGO" fontSize={f(15 * k)} fill="#aab5d4" textAnchor="middle">
        {date}
      </text>
      <text x={f(cx)} y={f(cy + 8 * k)} fontFamily="FiraGO" fontWeight={600} fontSize={f(fit(clock(now), 56 * k, 230 * k))} fill="#ffffff" textAnchor="middle">
        {clock(now)}
      </text>
      <text x={f(cx)} y={f(cy + 36 * k)} fontFamily="FiraGO" fontSize={f(15 * k)} fill="#aab5d4" textAnchor="middle">
        {`sun ${sunUp ? Math.round(sunNow) + '° up' : Math.round(-sunNow) + '° down'}`}
      </text>
      <text x={f(cx)} y={f(cy + 72 * k)} fontFamily="FiraGO" fontWeight={600} fontSize={f(17 * k)} fill="#ffffff" textAnchor="middle">
        {`${lengthText(daylight)} of daylight`}
      </text>
      <text x={f(cx)} y={f(cy + 90 * k)} fontFamily="FiraGO" fontSize={f(14 * k)} fill="#8d9bc0" textAnchor="middle">
        {changeText(daylight - daylightYesterday)}
      </text>
      <circle cx={f(cx)} cy={f(moonY + 12 * k)} r={f(moonR)} fill="#2b3350" />
      <path d={moonPath(cx, moonY + 12 * k, moonR, lit.phase)} fill="#eef1f8" />
      <text x={f(cx)} y={f(moonY + 44 * k)} fontFamily="FiraGO" fontSize={f(fit(moonText, 14 * k, 200 * k))} fill="#aab5d4" textAnchor="middle">
        {moonText}
      </text>
    </svg>
  )
}

