// Where the sun and the moon are, worked out from the time (low precision
// formulas, good to a few minutes for rise and set, a fraction of a degree
// for position). Angles in degrees unless a name says otherwise.

const RAD = Math.PI / 180

function days2000(epochMs: number) {
  return epochMs / 86400000 + 2440587.5 - 2451545.0
}

function wrap360(value: number) {
  const v = value % 360
  return v < 0 ? v + 360 : v
}

function obliquity(d: number) {
  return (23.439 - 0.0000004 * d) * RAD
}

// Right ascension and declination (radians) from ecliptic longitude and latitude.
function equatorial(lambda: number, beta: number, eps: number) {
  const ra = Math.atan2(Math.sin(lambda) * Math.cos(eps) - Math.tan(beta) * Math.sin(eps), Math.cos(lambda))
  const dec = Math.asin(Math.sin(beta) * Math.cos(eps) + Math.cos(beta) * Math.sin(eps) * Math.sin(lambda))
  return { ra, dec }
}

// Greenwich mean sidereal time, in degrees.
function sidereal(d: number) {
  return wrap360(280.46061837 + 360.98564736629 * d)
}

export function sunPosition(epochMs: number) {
  const d = days2000(epochMs)
  const g = wrap360(357.528 + 0.9856003 * d) * RAD
  const lambda = (wrap360(280.46 + 0.9856474 * d) + 1.915 * Math.sin(g) + 0.02 * Math.sin(2 * g)) * RAD
  return { ...equatorial(lambda, 0, obliquity(d)), distance: 149598000, d }
}

export function moonPosition(epochMs: number) {
  const d = days2000(epochMs)
  const L = wrap360(218.316 + 13.176396 * d) * RAD
  const M = wrap360(134.963 + 13.064993 * d) * RAD
  const F = wrap360(93.272 + 13.22935 * d) * RAD
  const lambda = L + 6.289 * RAD * Math.sin(M)
  const beta = 5.128 * RAD * Math.sin(F)
  return { ...equatorial(lambda, beta, obliquity(d)), distance: 385001 - 20905 * Math.cos(M), d }
}

// Altitude above the horizon, in degrees, of a body at ra/dec (radians).
function altitudeOf(body: { ra: number; dec: number; d: number }, latitude: number, longitude: number) {
  const hourAngle = (sidereal(body.d) + longitude) * RAD - body.ra
  const lat = latitude * RAD
  return Math.asin(Math.sin(lat) * Math.sin(body.dec) + Math.cos(lat) * Math.cos(body.dec) * Math.cos(hourAngle)) / RAD
}

export function sunAltitude(epochMs: number, latitude: number, longitude: number) {
  return altitudeOf(sunPosition(epochMs), latitude, longitude)
}

export function moonAltitude(epochMs: number, latitude: number, longitude: number) {
  return altitudeOf(moonPosition(epochMs), latitude, longitude)
}

// The point on Earth with the sun straight overhead.
export function subsolarPoint(epochMs: number) {
  const sun = sunPosition(epochMs)
  let longitude = (sun.ra / RAD - sidereal(sun.d)) % 360
  if (longitude < -180) longitude += 360
  if (longitude > 180) longitude -= 360
  return { latitude: sun.dec / RAD, longitude }
}

// The sun's altitude at a place, given the subsolar point (cheap, for a map).
export function sunAltitudeFrom(subsolar: { latitude: number; longitude: number }, latitude: number, longitude: number) {
  const lat = latitude * RAD
  const dec = subsolar.latitude * RAD
  const hourAngle = (longitude - subsolar.longitude) * RAD
  return Math.asin(Math.sin(lat) * Math.sin(dec) + Math.cos(lat) * Math.cos(dec) * Math.cos(hourAngle)) / RAD
}

// How much of the moon is lit (0..1) and where it is in its month:
// phase 0 new, 0.25 first quarter, 0.5 full, 0.75 last quarter.
export function moonIllumination(epochMs: number) {
  const s = sunPosition(epochMs)
  const m = moonPosition(epochMs)
  const phi = Math.acos(Math.sin(s.dec) * Math.sin(m.dec) + Math.cos(s.dec) * Math.cos(m.dec) * Math.cos(s.ra - m.ra))
  const inc = Math.atan2(s.distance * Math.sin(phi), m.distance - s.distance * Math.cos(phi))
  const angle = Math.atan2(
    Math.cos(s.dec) * Math.sin(s.ra - m.ra),
    Math.sin(s.dec) * Math.cos(m.dec) - Math.cos(s.dec) * Math.sin(m.dec) * Math.cos(s.ra - m.ra),
  )
  return {
    fraction: (1 + Math.cos(inc)) / 2,
    phase: 0.5 + (0.5 * inc * (angle < 0 ? -1 : 1)) / Math.PI,
  }
}

// The named phases are moments: within about a day of one, the moon is it.
export function moonPhaseName(phase: number) {
  if (phase < 0.03 || phase > 0.97) return 'New moon'
  if (phase < 0.22) return 'Waxing crescent'
  if (phase < 0.28) return 'First quarter'
  if (phase < 0.47) return 'Waxing gibbous'
  if (phase < 0.53) return 'Full moon'
  if (phase < 0.72) return 'Waning gibbous'
  if (phase < 0.78) return 'Last quarter'
  return 'Waning crescent'
}

// The moon drawn lit as it is: a path for the lit part of a disc.
export function moonPath(cx: number, cy: number, r: number, phase: number) {
  const waxing = phase < 0.5
  const inner = Math.abs(Math.cos(phase * Math.PI * 2)) * r
  const crescent = phase < 0.25 || phase > 0.75
  const outerSweep = waxing ? 1 : 0
  const innerSweep = waxing ? (crescent ? 0 : 1) : crescent ? 1 : 0
  return (
    `M${cx.toFixed(1)} ${(cy - r).toFixed(1)} A${r.toFixed(1)} ${r.toFixed(1)} 0 0 ${outerSweep} ${cx.toFixed(1)} ${(cy + r).toFixed(1)} ` +
    `A${inner.toFixed(1)} ${r.toFixed(1)} 0 0 ${innerSweep} ${cx.toFixed(1)} ${(cy - r).toFixed(1)} Z`
  )
}

